using UA.DataAccess.Interface.Common;
using UA.Entities;
using UA.Facade.DTO.Administration;
using UA.Facade.Interface.Admission;
using UA.Facade.Interface.Administration;
using UA.Facade.Interface.Integration;
using UA.Framework.Security;
using UA.Framework.Time;
using UA.Framework.Exceptions;
using System.Globalization;
namespace UA.Facade.Implementation.Admission;
public sealed class AdmissionReportJobs(IRepository<BackgroundJob> jobs,IRepository<AdmissionCircular> circulars,IRepository<Application> applications,IRepository<Applicant> applicants,IRepository<Department> departments,IRepository<AcademicTerm> terms,IRepository<Due> dues,IRepository<FeeType> rates,IRepository<Payment> payments,IRepository<PaymentAllocation> allocations,IRepository<RolePermission> grants,IUserAccessFacade access,ICurrentUser current,IClock clock,IUnitOfWork work,IPrivateReportStorage storage,IAcademicWorkbookWriter workbook,IExamPdfWriter pdf,IManualAuditService audit):IAdmissionReportJobs
{
 private static readonly string[] Statuses=["","Submitted","Paid","Result published","Enrolled","Selected"];
 private static bool Report(BackgroundJob j)=>j.JobType.StartsWith("AdmX:",StringComparison.Ordinal)||j.JobType.StartsWith("AdmP:",StringComparison.Ordinal);
 private int Actor=>current.UserId??throw new ForbiddenException();
 private async Task Authorize(int user,CancellationToken ct){var snap=await access.ForUserAsync(user,ct);var ids=snap.Assignments.Where(x=>!x.Scoped).Select(x=>x.RoleId).ToArray();var gg=await grants.ListAsync(g=>ids.Contains(g.RoleId)&&(g.PermissionCode=="admission.reports"||g.PermissionCode=="applications.review"),ct);if(!gg.Any(x=>x.PermissionCode=="admission.reports")||!gg.Any(x=>x.PermissionCode=="applications.review"))throw new ForbiddenException();}
 public async Task<int> EnqueueAsync(int circularId,int? departmentId,string? status,bool pdf){await Authorize(Actor,default);if(await circulars.FirstAsync(c=>c.CircularId==circularId)==null)throw new NotFoundException();int filter=Array.IndexOf(Statuses,status??"");if(filter<0)throw new BusinessRuleException("Choose a valid admission status.");if(departmentId.HasValue&&await departments.FirstAsync(d=>d.DepartmentId==departmentId)==null)throw new BusinessRuleException("Unknown department.");var type=$"{(pdf?"AdmP":"AdmX")}:{circularId}:{departmentId??0}:{filter}";if(type.Length>30)throw new BusinessRuleException("Invalid report parameters.");BackgroundJob? j=null;await work.ExecuteTransactionAsync(async ct=>{j=await jobs.FirstAsync(x=>x.RequestedBy==Actor&&x.JobType==type&&(x.Status=="Queued"||x.Status=="Running"),ct);if(j!=null)return;j=new BackgroundJob{RequestedBy=Actor,JobType=type,Status="Queued",CreatedAt=clock.Now};await jobs.AddAsync(j,ct);});return j!.JobId;}
 private async Task<BackgroundJob> Own(int id){await Authorize(Actor,default);var j=await jobs.FirstAsync(x=>x.JobId==id&&x.RequestedBy==Actor)??throw new NotFoundException();if(!Report(j))throw new NotFoundException();return j;}
 public async Task<JobDto> GetAsync(int id){var j=await Own(id);return new(j.JobId,j.JobType,j.RequestedBy,j.Status,j.ProgressPercent,j.CreatedAt,null);}
 public async Task<(byte[] Data,bool Pdf)> DownloadAsync(int id){var j=await Own(id);if(j.Status!="Completed"||j.FinishedAt==null||j.FinishedAt<clock.Now.AddHours(-24))throw new BusinessRuleException("Report is not ready or has expired. Request a new export.");await audit.LogAsync("Export","AdmissionReport",id.ToString(),"Download completed report");return(await storage.ReadReportAsync(id),j.JobType.StartsWith("AdmP:"));}
 public async Task<int?> NextAsync(CancellationToken ct)=>(await jobs.ListAsync(x=>(x.Status=="Queued"||x.Status=="Running")&&(x.JobType.StartsWith("AdmX:")||x.JobType.StartsWith("AdmP:")),ct)).OrderBy(x=>x.JobId).Select(x=>(int?)x.JobId).FirstOrDefault();
 public async Task ProcessAsync(int id,CancellationToken ct){var j=await jobs.FirstAsync(x=>x.JobId==id,ct)??throw new NotFoundException();if(!Report(j)||j.Status is not ("Queued" or "Running"))return;await Authorize(j.RequestedBy,ct);var parts=j.JobType.Split(':');if(parts.Length!=4||!int.TryParse(parts[1],out int circularId)||!int.TryParse(parts[2],out int dept)||!int.TryParse(parts[3],out int filter)||filter<0||filter>=Statuses.Length)throw new BusinessRuleException("Invalid report parameters.");j.Status="Running";j.ProgressPercent=5;await work.SaveChangesAsync(ct);
  var c=await circulars.FirstAsync(x=>x.CircularId==circularId,ct)??throw new NotFoundException();var term=await terms.FirstAsync(x=>x.Year==c.IntakeYear&&x.TermNo==1,ct)??throw new NotFoundException();var aa=(await applications.ListAsync(x=>x.CircularId==circularId&&(dept==0||x.DepartmentId==dept),ct)).OrderBy(x=>x.DepartmentId).ThenBy(x=>x.MeritRank??int.MaxValue).ToArray();var ds=await departments.ListAsync(ct:ct);var rr=await rates.ListAsync(ct:ct);var output=new List<string[]>();int processed=0;
  foreach(var chunk in aa.Chunk(300)){var ids=chunk.Select(x=>x.ApplicantId).ToArray();var people=(await applicants.ListAsync(x=>ids.Contains(x.ApplicantId),ct)).ToDictionary(x=>x.ApplicantId);var dd=await dues.ListAsync(x=>x.ApplicantId!=null&&ids.Contains(x.ApplicantId.Value)&&x.TermId==term.TermId&&x.EnrollmentId==null,ct);var did=dd.Select(x=>x.DueId).ToArray();var alloc=new List<PaymentAllocation>();foreach(var batch in did.Chunk(500))alloc.AddRange(await allocations.ListAsync(x=>batch.Contains(x.DueId),ct));var payIds=alloc.Select(x=>x.PaymentId).Distinct().ToArray();var good=new List<Payment>();var reversed=new HashSet<int>();foreach(var batch in payIds.Chunk(500)){good.AddRange(await payments.ListAsync(x=>batch.Contains(x.PaymentId)&&x.Status=="Successful"&&x.ReversesPaymentId==null,ct));foreach(var r in await payments.ListAsync(x=>x.ReversesPaymentId!=null&&batch.Contains(x.ReversesPaymentId.Value)&&x.Status=="Successful",ct))reversed.Add(r.ReversesPaymentId!.Value);}
   var byDue=alloc.ToLookup(x=>x.DueId);var byApplicant=dd.ToLookup(x=>x.ApplicantId);var valid=good.Where(x=>!reversed.Contains(x.PaymentId)).ToDictionary(x=>x.PaymentId);
   foreach(var a in chunk){bool Clear(string fee){var types=rr.Where(x=>x.DepartmentId==a.DepartmentId&&x.Name==fee).Select(x=>x.FeeTypeId).ToHashSet();var lines=byApplicant[a.ApplicantId].Where(x=>types.Contains(x.FeeTypeId)).ToArray();return lines.Length>0&&lines.All(x=>x.Status!="Reversed"&&byDue[x.DueId].Where(y=>valid.TryGetValue(y.PaymentId,out var pay)&&pay.ApplicantId==a.ApplicantId).Sum(y=>y.Amount)>=x.Amount);}var appPaid=Clear("Application");var enrollmentPaid=Clear("Registration")&&Clear("Tuition");var status=a.ApplicationStatus=="Submitted"&&appPaid?"Paid":a.ApplicationStatus;if(filter!=0&&status!=Statuses[filter])continue;output.Add([a.ApplicantId.ToString(),people[a.ApplicantId].FullName,ds.Single(x=>x.DepartmentId==a.DepartmentId).Name,status,a.TestMarks?.ToString(CultureInfo.InvariantCulture)??"",a.MeritRank?.ToString()??"",a.SelectionStatus??"",a.DocumentsVerified.ToString(),appPaid.ToString(),enrollmentPaid.ToString()]);}
   processed+=chunk.Length;j.ProgressPercent=(byte)Math.Min(85,5+(80L*processed/Math.Max(1,aa.Length)));await work.SaveChangesAsync(ct);
  }
  string[] headers=["Applicant ID","Name","Department","Status","Marks","Rank","Selection","Documents verified","Application fee cleared","Enrollment fee cleared"];var data=parts[0]=="AdmP"?pdf.Write("Admission report",headers,output.ToArray()):workbook.Write(headers,output);j.ProgressPercent=95;await work.SaveChangesAsync(ct);await storage.WriteReportAsync(id,data,ct);j.Status="Completed";j.ProgressPercent=100;j.FinishedAt=clock.Now;await work.SaveChangesAsync(ct);
 }
 public async Task FailAsync(int id,CancellationToken ct){var j=await jobs.FirstAsync(x=>x.JobId==id,ct);if(j==null||!Report(j)||j.Status=="Completed")return;j.Status="Failed";j.FinishedAt=clock.Now;await work.SaveChangesAsync(ct);await storage.DeleteReportAsync(id,ct);}
 public async Task CleanupAsync(CancellationToken ct){var cutoff=clock.Now.AddHours(-24);var old=await jobs.ListAsync(x=>x.FinishedAt!=null&&x.FinishedAt<cutoff&&(x.JobType.StartsWith("AdmX:")||x.JobType.StartsWith("AdmP:")),ct);foreach(var j in old)await storage.DeleteReportAsync(j.JobId,ct);}
}
